'use strict';

// Source of truth for named presets is generated by the authenticated server.
// This UI merely helps an administrator select concrete capabilities.
// Authorization and dependency checks are always revalidated on the server.
const readCatalog = id => {
  try {
    const value = JSON.parse(document.getElementById(id)?.textContent || 'null');
    return value && typeof value === 'object' ? value : null;
  } catch (_) {
    return null;
  }
};
const groupList = readCatalog('access-group-catalog') || [];
const groupDefaults = readCatalog('access-role-defaults') || {};
const groupMap = new Map(groupList.map(group => [group.id, group]));
const adminOnly = new Set(['users:manage', 'tokens:manage']);
const confidential = new Set(['calls:sensitive', 'calls:transcript:read']);

for (const form of document.querySelectorAll('form[data-access-editor]')) {
  const role = form.querySelector('[data-role-select]');
  const group = form.querySelector('[data-group-select]');
  const counter = form.querySelector('[data-grant-count]');
  const hint = form.querySelector('[data-group-hint]');
  const warning = form.querySelector('[data-risk-note]');
  const inputs = new Map([...form.querySelectorAll('input[name="grants"]')]
    .map(input => [input.value, input]));
  if (!role || !group || inputs.size === 0) continue;

  const checked = () => new Set([...inputs.values()]
    .filter(input => input.checked).map(input => input.value));

  const apply = capabilities => {
    for (const [name, input] of inputs) {
      input.checked = capabilities.has(name);
    }
  };

  const matchGroup = capabilities => {
    for (const item of groupList) {
      const values = new Set(item.grants);
      if (values.size === capabilities.size &&
          [...values].every(key => capabilities.has(key))) {
        return item.id;
      }
    }
    return 'custom';
  };

  const fixDependencies = changed => {
    const calls = inputs.get('calls:read');
    const metrics = inputs.get('metrics:read');
    const mcp = inputs.get('mcp:use');
    const sensitive = inputs.get('calls:sensitive');
    const transcript = inputs.get('calls:transcript:read');

    if (changed?.checked && [sensitive, transcript].includes(changed)) {
      if (calls) calls.checked = true;
    }
    if (changed === mcp && mcp?.checked && !calls?.checked && !metrics?.checked) {
      if (metrics) metrics.checked = true; // minimum useful MCP permission
    }
    if (calls && !calls.checked) {
      if (sensitive) sensitive.checked = false;
      if (transcript) transcript.checked = false;
    }
    if (mcp && !calls?.checked && !metrics?.checked) mcp.checked = false;
  };

  const render = ({syncGroup = false} = {}) => {
    const isAdmin = role.value === 'admin';
    if (isAdmin) {
      for (const checkbox of inputs.values()) {
        checkbox.checked = true;
        checkbox.disabled = true;
      }
      group.value = 'custom';
      group.disabled = true;
      if (hint) hint.textContent =
        'نقش مدیر کل تمام دسترسی‌ها را دارد. برای محدودسازی، نقش غیرمدیر انتخاب کنید.';
    } else {
      for (const [name, checkbox] of inputs) {
        checkbox.disabled = adminOnly.has(name);
        if (checkbox.disabled) checkbox.checked = false;
      }
      group.disabled = false;
      if (syncGroup) group.value = matchGroup(checked());
      if (hint) {
        const preset = groupMap.get(group.value);
        hint.textContent = preset ? preset.description :
          'این کاربر دارای مجوزهای سفارشی است. گروه‌های آماده فقط الگو هستند.';
      }
    }
    const selected = checked();
    if (counter) counter.textContent =
      new Intl.NumberFormat('fa-IR').format(selected.size) + ' مجوز فعال';
    if (warning) warning.hidden = isAdmin ||
      ![...confidential].some(name => selected.has(name));
  };

  group.addEventListener('change', () => {
    if (role.value !== 'admin') {
      const preset = groupMap.get(group.value);
      if (preset) {
        apply(new Set(preset.grants));
        fixDependencies();
      }
    }
    render();
  });

  role.addEventListener('change', () => {
    if (role.value !== 'admin') {
      const preset = groupMap.get(groupDefaults[role.value]);
      apply(new Set(preset?.grants || []));
      group.value = preset?.id || 'custom';
    }
    render();
  });

  for (const checkbox of inputs.values()) {
    checkbox.addEventListener('change', () => {
      if (role.value === 'admin') return;
      fixDependencies(checkbox);
      render({syncGroup: true});
    });
  }

  form.addEventListener('submit', event => {
    const elevated = role.value === 'admin' ||
      [...confidential].some(name => checked().has(name));
    const editing = form.dataset.accessEditor === 'edit';
    const message = elevated
      ? 'این تغییر دسترسی سطح بالا یا محرمانه ایجاد می‌کند. آیا مجوزهای نمایش‌داده‌شده را تأیید می‌کنید؟'
      : editing
        ? 'ذخیرهٔ تغییرات، نشست‌ها و توکن‌های فعلی این حساب را باطل می‌کند. ادامه می‌دهید؟'
        : null;
    if (message && !window.confirm(message)) event.preventDefault();
  });

  render();
}
